<?php $visitorHistorySearch = $staffServices && $tabKey === 'history'; ?>
<section class="service-panel service-request-list" <?= $visitorHistorySearch ? 'data-history-search' : '' ?>><h2><?= $tabKey === 'history' ? 'Visitor history' : ($staffServices ? 'Review requests' : 'Your requests') ?></h2>
<?php if ($visitorHistorySearch): ?>
<div class="service-form history-search-controls"><label class="field-label service-wide" for="visitorHistorySearch">Search visitor history<input id="visitorHistorySearch" type="search" data-history-search-input placeholder="Visitor, resident, unit, date or registration number" aria-describedby="visitorHistorySearchCount"></label></div>
<p id="visitorHistorySearchCount" role="status" aria-live="polite"><span data-history-search-count><?= count($requests) ?></span> matching registration(s)</p>
<p data-history-search-empty hidden>No visitor registrations match your search.</p>
<?php endif; ?>
<?php if (!$requests): ?><p><?= $tabKey === 'history' ? 'No past visitor registrations yet.' : 'No active visitor requests.' ?></p><?php endif; ?>
<?php foreach ($requests as $request): ?><?php $combinedParking=$linkedParking[(int)$request['id']]??null;$combinedControls=$staffServices&&canAccess('visitors.approve_all')&&$combinedParking&&in_array($combinedParking['status'],['pending','approved'],true)&&in_array($request['status'],['pending','approved'],true)&&$request['end_date']>=date('Y-m-d');$combinedReview=$combinedControls&&($request['status']==='pending'||$request['identity_status']!=='verified'||$combinedParking['status']==='pending'); ?><article class="service-request"<?php if ($visitorHistorySearch): ?> data-history-search-record="<?= serviceEscape(implode(' ', ['#'.$request['id'], $request['visitor_name'], $request['full_name'], $request['unit_number'], $request['visitor_contact'], $request['start_date'], $request['end_date'], $request['details'], str_replace('_', ' ', $request['status']), $request['identity_status'], $linkedParking[(int)$request['id']]['vehicle_plate'] ?? ''])) ?>"<?php endif; ?>><div class="service-request-heading"><h3>#<?= (int)$request['id'] ?> · <?= serviceEscape($request['request_kind'] === 'visitor' ? $request['visitor_name'] : $request['permit_type']) ?></h3><span class="service-status service-status-<?= serviceEscape($request['status']) ?>"><?= serviceEscape(ucfirst(str_replace('_', ' ', $request['status']))) ?><?= $request['end_date'] < date('Y-m-d') ? ' · expired' : '' ?></span></div>
<p class="service-request-meta"><?= serviceEscape($request['start_date']) ?><?= $request['start_date'] !== $request['end_date'] ? ' to ' . serviceEscape($request['end_date']) : '' ?> · Unit <?= serviceEscape($request['unit_number']) ?><?php if ($staffServices): ?> · <?= serviceEscape($request['full_name']) ?><?php endif; ?></p>
<?php if ($request['request_kind'] === 'visitor'): ?><p class="service-request-count">Number of visitors: <strong><?= (int)$request['visitor_count'] ?></strong></p><?php endif; ?>
<?php if ($serviceKind === 'visitor'): ?>
<?php if($combinedReview): ?><p><button type="button" class="service-btn" data-vp-review-request="<?= (int)$combinedParking['id'] ?>" data-csrf="<?= serviceEscape(workflowCsrfToken()) ?>">Review ID &amp; Approve Parking</button></p><p>Verify the ID, approve the visit and assign parking together in one review.</p><?php endif; ?>
<section class="visitor-identity-summary" aria-label="Identity verification">
    <p>Identity verification: <span class="service-status service-status-<?= serviceEscape($request['identity_status'] === 'verified' ? 'approved' : $request['identity_status']) ?>"><?= serviceEscape(ucfirst($request['identity_status'])) ?></span><?php if ($request['id_type']): ?> · <?= serviceEscape($request['id_type']) ?><?php endif; ?></p>
    <?php if ($request['identity_review_note']): ?><p>Identity review note: <?= serviceEscape($request['identity_review_note']) ?></p><?php endif; ?>
    <?php if (empty($request['id_document_name'])): ?><p><?= $request['id_deleted_at'] ? 'The ID document has been deleted under the retention policy.' : 'An ID document is required before this visitor can receive an active QR pass.' ?></p><?php endif; ?>
    <?php if ($staffServices && canAccess('visitors.identity.review') && $request['id_document_name'] && !visitorIdExpired($request)): ?>
<?php if($combinedControls): ?><details><summary>Separate ID review / rejection</summary><?php endif; ?>
        <a class="service-btn service-btn-secondary" href="../visitor_id_document.php?request_id=<?= (int)$request['id'] ?>" target="_blank" rel="noopener noreferrer">Review ID document</a>
        <?php if ($request['id_number_last4']): ?><p>ID reference ending: •••• <?= serviceEscape($request['id_number_last4']) ?></p><?php endif; ?>
        <?php if (in_array($request['status'], ['pending','approved'], true) && $request['end_date'] >= date('Y-m-d')): ?>
        <form method="post" action="<?= serviceEscape($visitorFormAction) ?>" class="service-actions visitor-identity-review"><?= workflowCsrfField() ?><input type="hidden" name="action" value="review_identity"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><input type="hidden" name="identity_version" value="<?= visitorIdentityVersion($request) ?>">
            <label for="identity-note-<?= (int)$request['id'] ?>">Identity review note (required for rejection)</label><input id="identity-note-<?= (int)$request['id'] ?>" name="identity_review_note" maxlength="500" placeholder="Give a reason if the ID cannot be verified">
            <button name="identity_decision" value="verified">Verify identity</button><button class="service-btn-danger" name="identity_decision" value="rejected">Reject identity</button>
        </form><?php endif; ?><?php if($combinedControls): ?></details><?php endif; ?>
    <?php elseif (!$staffServices && in_array($request['status'], ['pending','approved'], true) && $request['end_date'] >= date('Y-m-d')): ?>
        <details class="visitor-identity-replace"><summary><?= $request['id_document_name'] ? 'Submit a replacement ID' : 'Submit required ID' ?></summary>
            <p>A replacement must be reviewed again. Any previous QR code is revoked.</p>
            <form method="post" action="<?= serviceEscape($visitorFormAction) ?>" enctype="multipart/form-data" class="service-form" data-visitor-id-form><?= workflowCsrfField() ?><input type="hidden" name="action" value="replace_identity"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>">
                <?php $identityFieldPrefix = 'visitor-' . (int)$request['id']; include __DIR__ . '/visitor_identity_fields.php'; ?>
                <div class="service-wide service-submit"><button type="submit">Submit ID for review</button></div>
            </form>
        </details>
    <?php endif; ?>
</section>
<?php endif; ?>
<p class="service-request-description"><?= serviceEscape($request['details']) ?></p><?php if ($request['admin_notes']): ?><p>Review note: <?= serviceEscape($request['admin_notes']) ?></p><?php endif; ?>
<div class="service-request-actions"><?php if ($serviceKind === 'visitor' && $canRequestParking): ?><?php $visitorParking = $linkedParking[(int)$request['id']] ?? null; ?><?php if ($visitorParking): ?><p class="service-parking-status">Parking: <strong><?= serviceEscape(ucfirst($visitorParking['status'])) ?></strong> · <?= serviceEscape($visitorParking['vehicle_plate']) ?> <a class="service-btn service-btn-secondary" href="parking.php#parking-request-<?= (int)$visitorParking['id'] ?>">View parking request</a></p><?php endif; ?><?php if (!$staffServices && (!$visitorParking || in_array($visitorParking['status'], ['cancelled','rejected'], true)) && in_array($request['status'], ['pending','approved','checked_in'], true) && $request['end_date'] >= date('Y-m-d')): ?><p><a class="service-btn service-btn-secondary" href="parking.php?visitor_id=<?= (int)$request['id'] ?>#visitorParking">Request parking for this visitor</a></p><?php endif; ?><?php endif; ?>
<?php if (in_array($request['status'], ['approved','checked_in','checked_out'], true) && ($serviceKind !== 'visitor' || visitorAccessApprovalsComplete($db, $request) || in_array($request['status'], ['checked_in','checked_out'], true))): ?><a class="service-btn service-btn-secondary" href="<?= serviceEscape(residentServicePassUrl($request)) ?>">View access pass</a><?php elseif ($serviceKind === 'visitor' && in_array($request['status'], ['pending','approved'], true)): ?><p class="service-parking-status">QR pass awaiting identity, visit and any parking approvals.</p><?php endif; ?>
<?php if ($staffServices && $request['status'] === 'pending' && $request['end_date'] >= date('Y-m-d')): ?><?php if($combinedReview): ?><details><summary>Separate visit decision / rejection</summary><?php endif; ?><form method="post" action="<?= serviceEscape($visitorFormAction) ?>" class="service-actions"><?= workflowCsrfField() ?><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><input name="admin_notes" maxlength="500" placeholder="Visit review note"><button name="decision" value="approved">Approve visit</button><button name="decision" value="rejected">Reject visit</button></form><?php if($combinedReview): ?></details><?php endif; ?>
<?php elseif (!$staffServices && in_array($request['status'], ['pending','approved'], true)): ?><form method="post" action="<?= serviceEscape($visitorFormAction) ?>" class="service-actions"><?= workflowCsrfField() ?><input type="hidden" name="action" value="cancel"><input type="hidden" name="request_id" value="<?= (int)$request['id'] ?>"><button type="submit" class="service-btn service-btn-danger">Cancel request</button></form><?php endif; ?>
</div></article><?php endforeach; ?></section>
